sueDate": "2025-02-28+01:00", "cbc:IssueTime": "15:20:07+01:00", "cbc:VersionID": "01", "cbc:RegulatoryDomain": "32014L0024", "cbc:NoticeTypeCode": {"@listName": "competition", "#text": "cn-standard"}, "cbc:NoticeLanguageCode": {"@listName": "language", "#text": "FRA"}, "cac:ContractingParty": {"cbc:BuyerProfileURI": "https://pays-ancenis.e-marchespublics.com", "cac:ContractingPartyType": {"cbc:PartyTypeCode": {"@listName": "buyer-legal-type", "#text": "body-pl"}}, "cac:ContractingActivity": {"cbc:ActivityTypeCode": {"@listName": "authority-activity", "#text": "gen-pub"}}, "cac:Party": {"cac:PartyIdentification": {"cbc:ID": "ORG-0001"}}}, "cac:TenderingTerms": {"cac:TendererQualificationRequest": {"cac:SpecificTendererRequirement": {"cbc:TendererRequirementTypeCode": {"@listName": "exclusion-ground", "#text": "nati-ground"}, "cbc:Description": {"@languageID": "FRA", "#text": "Se référer aux documents de la consultation"}}}, "cac:LotDistribution": {"cbc:MaximumLotsAwardedNumeric": "9", "cbc:MaximumLotsSubmittedNumeric": "9"}}, "cac:TenderingProcess": {"cbc:Description": {"@languageID": "FRA", "#text": "La consultation est passée en application des articles L 2124-2, R 2124-2, R 2161-2 à R 2161-5 du code de la commande publique (CCP), sous la forme d'un appel d'offres ouvert.
Chaque marché est un accord-cadre à bons de commande qui donnera lieu à l'attribution d'un marché à un opérateur unique pour la durée du marché, passé en application des articles R 2162-1 à R 2162-6 et R 2162-13 à R 2162-14 du code de la commande publique."}, "cbc:ProcedureCode": {"@listName": "procurement-procedure-type", "#text": "open"}}, "cac:ProcurementProject": {"cbc:ID": "2025TRANSCOL", "cbc:Name": {"@languageID": "FRA", "#text": "Transport collectif de personnes pour les besoins de la COMPA - 9 lots"}, "cbc:Description": {"@languageID": "FRA", "#text": "La présente consultation a pour objet le transport collectif de personnes pour les besoins de la Communauté de Communes du Pays d'Ancenis (COMPA). Elle se décompose en 9 lots distincts, traités en marchés séparés."}, "cbc:ProcurementTypeCode": {"@listName": "contract-nature", "#text": "services"}, "cac:RequestedTenderTotal": {"ext:UBLExtensions": {"ext:UBLExtension": {"ext:ExtensionContent": {"efext:EformsExtension": {"efbc:FrameworkMaximumAmount": {"@currencyID": "EUR", "#text": "908000"}}}}}}, "cac:MainCommodityClassification": {"cbc:ItemClassificationCode": {"@listName": "cpv", "#text": "60140000"}}}, "cac:ProcurementProjectLot": [{"cbc:ID": {"@schemeName": "Lot", "#text": "LOT-0001"}, "cac:TenderingTerms": {"ext:UBLExtensions": {"ext:UBLExtension": {"ext:ExtensionContent": {"efext:EformsExtension": {"efac:SelectionCriteria": {"cbc:CriterionTypeCode": {"@listName": "selection-criterion", "#text": "tp-abil"}, "cbc:Name": {"@languageID": "FRA", "#text": "Pièces relatives à la candidature"}, "cbc:Description": {"@languageID": "FRA", "#text": "Pour chacun des lots, les éléments de candidature sont constitués par l'ensemble des pièces suivantes :
1) Une lettre de candidature DC1 ou équivalent (notamment DUME tel que prévu au R 2143-4 CCP)) comprenant la déclaration sur l'honneur conforme à l'article R 2143-3 du code de la commande publique : 
 " Le candidat individuel, ou chaque membre du groupement, déclare sur l'honneur n'entrer dans aucun des cas mentionnés aux articles L. 2141-1 à L. 2141-5 et L. 2141-7 à L. 2141-11 du code de la commande publique notamment qu'il satisfait aux obligations concernant l'emploi des travailleurs handicapés définies aux articles L. 5212-1 à L. 5212-11 du code du travail. "

2) A des fins de vérification de l'aptitude à exécuter l'activité professionnelle, de la capacité économique et financière et des capacités techniques et professionnelles du candidat (DC2 ou équivalent) : 
- une déclaration concernant le chiffre d'affaires global du candidat réalisé au cours des trois derniers exercices disponibles ;
- une liste des principales références des 3 dernières années avec indications des dates, montants et destinataires publics ou privés des prestations ;
- les certificats de qualification et capacités professionnelles, notamment copie de l'autorisation préfectorale à exécuter les services de transport, copie du certificat de capacité professionnelle au transport national et international par route et copie de la licence communautaire en cours de validité;
- une liste des moyens humains généraux ;
- une liste des moyens matériels généraux.

- La copie du (ou des) jugement(s) prononcé(s), si le candidat est en redressement judiciaire :
o pour le candidat établi dans un Etat autre que la France, un certificat établi par les administrations et organismes du pays d'origine dans les mêmes conditions que celles prévues ci-dessus pour les candidats établies en France ;
o lorsqu'un tel certificat n'est pas délivré dans le pays concerné, il peut être remplacé par une déclaration sous serment, ou dans les Etats où un tel serment n'existe pas, par une déclaration solennelle faite par l'intéressé devant l'autorité judiciaire ou administrative compétente, un notaire ou un organisme professionnel qualifié du pays.

